int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int ret = 0;
    int alloc_order = 0;
    int sg_ent = 0;
    int i;
    size_t align_mask = 512 - 1;  // Assume sector size is 512 bytes
    size_t align_size;
    size_t page_size = 4096;  // Assume standard 4KB pages
    void *page = NULL;

    if (buff_size <= 0)
        return -EINVAL;

    align_size = (buff_size + align_mask) & ~align_mask;
    if (align_size > schp->bufflen)
        return -ENOMEM;

    for (i = 0; i < SG_DEF_MAX; i++) {
        page = (void *)__get_free_pages(GFP_KERNEL, alloc_order);
        if (!page) {
            ret = -ENOMEM;
            goto cleanup;
        }

        schp->sg[sg_ent].address = (unsigned long)page;
        schp->sg[sg_ent].length = page_size << alloc_order;
        sg_ent++;

        if (align_size <= (size_t)page_size << alloc_order)
            break;

        align_size -= page_size << alloc_order;
    }

    if (align_size != 0) {
        schp->sg[sg_ent].address = (unsigned long)page + (align_size - 512);
        schp->sg[sg_ent].length = 512;
        sg_ent++;
    }

    schp->k_use = sg_ent;
    return 0;

cleanup:
    for (i = 0; i < sg_ent; i++) {
        free_pages((unsigned long)schp->sg[i].address, 0);
    }
    return ret;
}

int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int k, order, ret = 0;
    size_t align_size = 0;

    if (!buff_size)
        return 0;

    align_size = (buff_size + (1 << sfp->device->sector_shift) - 1) &
                 (~((size_t)(1 << sfp->device->sector_shift) - 1));

    if (align_size != (size_t)buff_size)
        return -EINVAL;

    schp->k_use = 0;

    for (k = 0; k < SG_MAX_INDIRECT; ++k) {
        order = get_order(align_size);
        schp->sg_cpu[k] = __get_free_pages(GFP_ATOMIC | __GFP_HIGH, order);
        if (!schp->sg_cpu[k]) {
            ret = -ENOMEM;
            break;
        }

        schp->sg_dma[k] = virt_to_phys((void *)schp->sg_cpu[k]);
        schp->sg_count[k] = align_size;
        schp->k_use++;
    }

    if (ret < 0) {
        for (k = 0; k < schp->k_use; ++k) {
            free_pages((unsigned long)schp->sg_cpu[k], get_order(schp->sg_count[k]));
        }
        schp->k_use = 0;
    }

    return (ret < 0) ? ret : (int)schp->k_use;
}

int build_indirect_sgl(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int k, result = 0;
    unsigned int sg_ent = 0;
    unsigned int alloc_order = 0;
    struct sg_page *sp;

    if (unlikely(buff_size <= 0)) {
        return -EINVAL;
    }

    buff_size = (buff_size + sfp->device_sectorsize - 1) & ~(sfp->device_sectorsize - 1);

    while (1 << alloc_order < (buff_size >> sfp->device_pageshift))
        alloc_order++;

    for (k = 0; k < SG_DEF_RESERVED_SIZE; ++k) {
        sp = (struct sg_page *)kmalloc(sizeof(struct sg_page), GFP_ATOMIC);
        if (!sp) {
            result = -ENOMEM;
            break;
        }

        sp->data = __get_free_pages(GFP_ATOMIC, alloc_order);
        if (!sp->data) {
            kfree(sp);
            result = -ENOMEM;
            break;
        }

        sp->data_len = 1 << (alloc_order + PAGE_SHIFT);
        schp->setup.sbp[sg_ent].data = sp->data;
        schp->setup.sbp[sg_ent].data_len = sp->data_len;
        schp->setup.sbp[sg_ent].page = sp;
        sg_ent++;
    }

    if (unlikely(result < 0)) {
        while (sg_ent--) {
            struct sg_page *sp = schp->setup.sbp[sg_ent].page;
            if (sp) {
                free_pages(sp->data, get_order(sp->data_len));
                kfree(sp);
            }
        }
        return result;
    }

    schp->k_ref = SG_K_REF;
    schp->sg_count = sg_ent;
    return 0;
}

int build_indirect_scatter_list(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int k, order, result;
    size_t align_mask;
    unsigned int nents;
    Sg_scat *s_cat;

    if (!schp || !sfp)
        return -EINVAL;

    align_mask = sfp->device->sector_size - 1;
    buff_size = (buff_size + align_mask) & ~align_mask;

    nents = buff_size / (1 << sfp->device->page_order);
    if (!nents)
        return -EINVAL;

    schp->kiov = kmalloc(sizeof(*schp->kiov), GFP_KERNEL);
    if (!schp->kiov)
        return -ENOMEM;

    schp->kiov[0].iov_base = NULL;
    schp->kiov[0].iov_len = buff_size;
    schp->kiov[0].count = 0;

    s_cat = schp->setup_scat;
    schp->setup_scat = NULL;
    schp->res_used = 0;

    for (k = 0; k < nents; ++k) {
        order = sfp->device->page_order;
        s_cat = sg_alloc_table_nob(s_cat, 1 << order, GFP_KERNEL | __GFP_RETRY_MAYFAIL);
        if (!s_cat) {
            result = -ENOMEM;
            break;
        }
        schp->setup_scat = s_cat;
        ++schp->res_used;
    }

    if (result < 0) {
        while (schp->setup_scat != s_cat) {
            sg_free_table(s_cat, 1 << sfp->device->page_order);
            ++s_cat;
        }
        kfree(schp->kiov);
        return result;
    }

    return schp->res_used;
}

int build_indirect_sg_list(Sg_scatter_hold *schp, Sg_fd *sfp, int buff_size) {
    int order = 0;  // Assuming default order for allocation
    int sg_count = 0;
    int ret = 0;

    // Align buffer size to sector size (assuming 512-byte sector)
    buff_size = (buff_size + 511) & ~511;

    // Initialize scatter-gather table
    sg_count = sg_table_alloc(schp, buff_size);

    if (sg_count < 0) {
        return sg_count; // Returns error code
    }

    // Allocate memory for pages with retries
    while (sg_count > 0) {
        void *page = alloc_pages(order, GFP_KERNEL);

        if (!page) {
            // Free previously allocated pages
            while (sg_count > 0) {
                free_pages(page, order);
                sg_count--;
            }
            return -ENOMEM;
        }

        // Assign page to scatter-gather element
        sg_set_page(&schp->sg[sg_count - 1], page, buff_size, 0);
        buff_size -= PAGE_SIZE << order;
        sg_count--;
    }

    // Log allocation success
    printk(KERN_INFO "Indirect SG list built successfully with %d elements.\n", sg_count);

    return 0;
}
